// GIVEN — do not change.
class Node {
    int key;
    Node left, right;

    Node(int k) {
        key = k;
    }
}

public class Queries {

    static Integer kthSmallest(Node t, int k) {
        int[] left = {k};
        return kth(t, left);
    }

    static Integer lca(Node t, int a, int b) {
        if (!contains(t, a) || !contains(t, b)) {
            return null;
        }
        while (t != null) {
            if (a < t.key && b < t.key) {
                t = t.left;
            } else if (a > t.key && b > t.key) {
                t = t.right;
            } else {
                return t.key; // a and b are on different sides (or one of them is t)
            }
        }
        return null;
    }

    private static Integer kth(Node t, int[] left) {
        if (t == null) {
            return null;
        }
        Integer r = kth(t.left, left);
        if (r != null) {
            return r;
        }
        if (--left[0] == 0) {
            return t.key;
        }
        return kth(t.right, left);
    }

    private static boolean contains(Node t, int key) {
        while (t != null && t.key != key) {
            t = key < t.key ? t.left : t.right;
        }
        return t != null;
    }
}

import java.util.*;

// Grader test class (do not edit): one command per input line; after each command it prints the result and the
// state read from the REAL links of your structure (Kiem follows the fields node by node).
public class KiemTra {
    static String[] p;

    static int n(int i) {
        return Integer.parseInt(p[i]);
    }

    static Node insert(Node t, int k) {
        if (t == null) {
            return new Node(k);
        }
        if (k < t.key) {
            t.left = insert(t.left, k);
        } else if (k > t.key) {
            t.right = insert(t.right, k);
        }
        return t;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Node t = null;
        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.isEmpty()) {
                continue;
            }
            p = line.split("\\s+");
            String r = "ok";
            try {
                if (p[0].equals("INS")) {
                    for (int i = 1; i < p.length; i++) {
                        t = insert(t, n(i));
                    }
                } else if (p[0].equals("K")) {
                    r = String.valueOf(Queries.kthSmallest(t, n(1)));
                } else {
                    r = String.valueOf(Queries.lca(t, n(1), n(2)));
                }
            } catch (RuntimeException e) {
                r = "THROWS " + Kiem.ten(e);
            }
            System.out.println(line + " -> " + r);
        }
    }
}

